def replace_block(src,label,body):
    pat=re.compile(r"(?ms)^("+re.escape(label)+r":\n)(.*?^\tdone\n?)")
    m=pat.search(src)
    if not m: raise RuntimeError(f"missing text block {label}")
    return src[:m.start()]+m.group(1)+body.rstrip()+"\n"+src[m.end():]
def patch(root,apply):
    changed=0
    for rel,mapping in P["repls"].items():
        path=root/rel
        src=path.read_text(encoding="utf-8"); old=src
        for a,b in P["raw"].get(rel,[]): 
            if a in src: src=src.replace(a,b,1)
        for label,body in mapping.items(): src=replace_block(src,label,body)
        if src!=old:
            changed+=1
            if apply: path.write_text(src,encoding="utf-8")
            print(("patched " if apply else "would patch ")+rel)
    return changed
def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("repo",nargs="?",default=".")
    ap.add_argument("--apply",action="store_true")
    a=ap.parse_args()
    n=patch(Path(a.repo),a.apply)
    print(f"Bank $56: {n} file(s) changed; 130 recovered text labels plus raw menu/egg/mail data.")
if __name__=="__main__": main()
